+/**
+ * Redacts Telegram bot tokens from a string.
+ * Bot tokens follow the pattern: <digits>:<alphanumeric-and-special-chars>
+ * They typically appear in URLs like https://api.telegram.org/bot<TOKEN>/method
+ */
+const BOT_TOKEN_PATTERN = /\b(\d{8,10}):[A-Za-z0-9_-]{35}\b/g;
+
+export function redactBotToken(input: string): string {
+  return input.replace(BOT_TOKEN_PATTERN, '[REDACTED_BOT_TOKEN]');
+}
+
+export function redactSensitive(input: string): string {
+  return redactBotToken(input);
+}
