+/**
+ * Escapes special characters in a string for use in RediSearch tag queries.
+ * RediSearch has special syntax characters that must be escaped with a backslash
+ * to be treated as literal values rather than query operators.
+ *
+ * @param value - The string value to escape
+ * @returns The escaped string safe for use in RediSearch tag queries
+ */
+export function escapeRediSearchTagValue(value: string): string {
+  // Escape all RediSearch special characters by prefixing with backslash
+  // Special chars: - . < > { } [ ] " ' : ; ! @ # $ % ^ & * ( ) + = ~ | \ ? /
+  return value.replace(
+    /[-.<>{}\[\]"':;!@#$%^&*()+\=~|\\?/]/g,
+    (char) => `\\${char}`
+  );
+}
