+/**
+ * Parses a Vary header value and returns an array of lowercase header names.
+ *
+ * @param vary The value of the Vary response header
+ * @returns Array of header names that the response varies on
+ */
+export function parse(vary: string): string[] {
+  if (!vary) return [];
+
+  // Vary: * means the response varies on everything - not cacheable in a shared context
+  if (vary.trim() === '*') return ['*'];
+
+  return vary
+    .split(',')
+    .map((h) => h.trim().toLowerCase())
+    .filter((h) => h.length > 0);
+}
+
+export function matches(varyHeaders: string[], requestHeaders1: Record<string, string | undefined>, requestHeaders2: Record<string, string | undefined>): boolean {
+  if (varyHeaders.includes('*')) return false;
+  return varyHeaders.every((header) => requestHeaders1[header] === requestHeaders2[header]);
+}
