+import { URL } from 'url';
+import * as net from 'net';
+
+/**
+ * Checks if an IP address is a private/internal address that should not be
+ * accessible via SSRF.
+ */
+function isPrivateIP(ip: string): boolean {
+  // IPv4 private ranges
+  const privateRanges = [
+    /^127\./, // Loopback
+    /^10\./, // Class A private
+    /^172\.(1[6-9]|2[0-9]|3[0-1])\./, // Class B private
+    /^192\.168\./, // Class C private
+    /^169\.254\./, // Link-local (AWS metadata, etc.)
+    /^0\./, // Current network
+    /^100\.(6[4-9]|[7-9][0-9]|1[0-1][0-9]|12[0-7])\./, // Shared address space
+    /^198\.1[89]\./, // Benchmarking
+    /^::1$/, // IPv6 loopback
+    /^fc00:/i, // IPv6 unique local
+    /^fd/i, // IPv6 unique local
+    /^fe80:/i, // IPv6 link-local
+    /^::ffff:(127\.|10\.|172\.(1[6-9]|2[0-9]|3[0-1])\.|192\.168\.|169\.254\.|0\.)/, // IPv4-mapped IPv6
+  ];
+
+  return privateRanges.some((range) => range.test(ip));
+}
+
+/**
+ * Validates that a custom host URL does not point to internal/private network
+ * resources. This prevents SSRF attacks via the x-portkey-custom-host header.
+ *
+ * @param customHost - The custom host URL to validate
+ * @returns true if the host is safe to use, false if it targets internal resources
+ */
+export function isValidCustomHost(customHost: string): boolean {
+  try {
+    // Ensure the URL has a protocol for proper parsing
+    let urlStr = customHost;
+    if (!urlStr.match(/^https?:\/\//i)) {
+      urlStr = 'https://' + urlStr;
+    }
+
+    const parsed = new URL(urlStr);
+    const hostname = parsed.hostname;
+
+    // Block common internal hostnames
+    const blockedHostnames = [
+      'localhost',
+      'metadata.google.internal',
+      'metadata.google',
+      'kubernetes.default',
+      'kubernetes.default.svc',
+    ];
+
+    const lowerHostname = hostname.toLowerCase();
+    if (blockedHostnames.includes(lowerHostname)) {
+      return false;
+    }
+
+    // Block if hostname ends with .internal or .local
+    if (lowerHostname.endsWith('.internal') || lowerHostname.endsWith('.local')) {
+      return false;
+    }
+
+    // Check if hostname is an IP address and if so, whether it's private
+    if (net.isIP(hostname)) {
+      if (isPrivateIP(hostname)) {
+        return false;
+      }
+    }
+
+    return true;
+  } catch {
+    // If URL parsing fails, reject it
+    return false;
+  }
+}
