+/**
+ * Sanitize HTML string to prevent XSS attacks.
+ * Removes dangerous elements and attributes while preserving safe inline formatting.
+ */
+export function sanitizeHTML(html: string): string {
+	if (!html) return html;
+
+	const parser = new DOMParser();
+	const doc = parser.parseFromString(`<body>${html}</body>`, 'text/html');
+	const body = doc.body;
+
+	sanitizeNode(body);
+
+	return body.innerHTML;
+}
+
+const DANGEROUS_TAGS = new Set([
+	'script', 'iframe', 'object', 'embed', 'applet', 'form',
+	'input', 'textarea', 'select', 'button', 'link', 'meta',
+	'base', 'frame', 'frameset', 'svg', 'math',
+]);
+
+const DANGEROUS_ATTRIBUTES = new Set([
+	'srcdoc', 'formaction', 'xlink:href', 'data',
+]);
+
+const EVENT_HANDLER_PATTERN = /^on/i;
+
+function sanitizeNode(node: Node): void {
+	const children = Array.from(node.childNodes);
+
+	for (const child of children) {
+		if (child instanceof Element) {
+			if (DANGEROUS_TAGS.has(child.tagName.toLowerCase())) {
+				child.remove();
+				continue;
+			}
+
+			for (const attr of Array.from(child.attributes)) {
+				if (DANGEROUS_ATTRIBUTES.has(attr.name.toLowerCase()) || EVENT_HANDLER_PATTERN.test(attr.name)) {
+					child.removeAttribute(attr.name);
+				}
+			}
+
+			sanitizeNode(child);
+		}
+	}
+}
