+/**
+ * Server-side sanitization for Block Editor content to prevent stored XSS.
+ * Strips dangerous HTML elements and attributes from block data.
+ */
+
+const DANGEROUS_TAG_PATTERN = /<\s*\/?\s*(script|iframe|object|embed|applet|form|input|textarea|select|button|link|meta|base|frame|frameset)\b[^>]*>/gi;
+const EVENT_HANDLER_PATTERN = /\s+on\w+\s*=\s*(?:"[^"]*"|'[^']*'|[^\s>]+)/gi;
+const SRCDOC_PATTERN = /\s+srcdoc\s*=\s*(?:"[^"]*"|'[^']*'|[^\s>]+)/gi;
+const JAVASCRIPT_URI_PATTERN = /\s+(href|src|action|formaction)\s*=\s*(?:"javascript:[^"]*"|'javascript:[^']*')/gi;
+const DATA_URI_SCRIPT_PATTERN = /\s+(href|src)\s*=\s*(?:"data:text\/html[^"]*"|'data:text\/html[^']*')/gi;
+
+export function sanitizeHTMLString(html: string): string {
+	if (!html || typeof html !== 'string') return html;
+
+	let sanitized = html;
+
+	// Remove dangerous tags entirely
+	sanitized = sanitized.replace(DANGEROUS_TAG_PATTERN, '');
+
+	// Remove event handler attributes
+	sanitized = sanitized.replace(EVENT_HANDLER_PATTERN, '');
+
+	// Remove srcdoc attributes
+	sanitized = sanitized.replace(SRCDOC_PATTERN, '');
+
+	// Remove javascript: URIs
+	sanitized = sanitized.replace(JAVASCRIPT_URI_PATTERN, '');
+
+	// Remove data: URIs that could contain scripts
+	sanitized = sanitized.replace(DATA_URI_SCRIPT_PATTERN, '');
+
+	return sanitized;
+}
+
+export function sanitizeBlockEditorContent(content: Record<string, any>): Record<string, any> {
+	if (!content || !Array.isArray(content.blocks)) return content;
+
+	const sanitized = { ...content };
+
+	sanitized.blocks = content.blocks.map((block: Record<string, any>) => {
+		if (!block.data) return block;
+
+		const sanitizedBlock = { ...block, data: { ...block.data } };
+
+		for (const [key, value] of Object.entries(sanitizedBlock.data)) {
+			if (typeof value === 'string') {
+				sanitizedBlock.data[key] = sanitizeHTMLString(value);
+			}
+		}
+
+		return sanitizedBlock;
+	});
+
+	return sanitized;
+}

