+import type { Filter } from '@directus/types';
+
+/**
+ * Fields that should never be searchable/filterable due to sensitivity
+ */
+const CONCEALED_FIELDS: Record<string, string[]> = {
+	directus_users: ['password', 'token', 'tfa_secret'],
+};
+
+/**
+ * Strip concealed fields from a filter to prevent enumeration attacks.
+ * Even though values are masked in output, allowing filters on these fields
+ * enables attackers to confirm the existence of specific values.
+ */
+export function stripConcealedFieldsFromFilter(filter: Filter, collection: string): Filter {
+	const concealedFields = CONCEALED_FIELDS[collection];
+
+	if (!concealedFields || !filter) {
+		return filter;
+	}
+
+	return removeConcealedKeys(filter, concealedFields);
+}
+
+function removeConcealedKeys(filter: Filter, concealedFields: string[]): Filter {
+	const result: Filter = {};
+
+	for (const [key, value] of Object.entries(filter)) {
+		if (key === '_and' || key === '_or') {
+			if (Array.isArray(value)) {
+				const cleaned = value
+					.map((subFilter: Filter) => removeConcealedKeys(subFilter, concealedFields))
+					.filter((subFilter: Filter) => Object.keys(subFilter).length > 0);
+
+				if (cleaned.length > 0) {
+					result[key] = cleaned;
+				}
+			}
+		} else if (concealedFields.includes(key)) {
+			// Skip concealed fields - do not include them in the filter
+			continue;
+		} else {
+			result[key] = value;
+		}
+	}
+
+	return result;
+}
