+const ALLOWED_HACKMD_HOSTS = [
+  "api.hackmd.io",
+  "api.hackmd.dev",
+];
+
+/**
+ * Validates that a given URL is a legitimate HackMD API endpoint.
+ * This prevents SSRF attacks by ensuring only known HackMD API hosts are used.
+ */
+export function isValidHackmdApiUrl(url: string): boolean {
+  try {
+    const parsed = new URL(url);
+
+    // Only allow HTTPS
+    if (parsed.protocol !== "https:") {
+      return false;
+    }
+
+    // Check against allowlist of known HackMD API hosts
+    const hostname = parsed.hostname.toLowerCase();
+    for (const allowed of ALLOWED_HACKMD_HOSTS) {
+      if (hostname === allowed || hostname.endsWith(`.${allowed}`)) {
+        return true;
+      }
+    }
+
+    return false;
+  } catch {
+    return false;
+  }
+}

