+import { getOperationAST, parse } from 'graphql';
+
+/**
+ * Checks if a GraphQL query is an introspection query.
+ * @param {string|object} query - The GraphQL query string or parsed document.
+ * @returns {boolean} True if the query is an introspection query.
+ */
+export function isIntrospectionQuery(query) {
+  try {
+    const document = typeof query === 'string' ? parse(query) : query;
+    const operation = getOperationAST(document);
+    if (!operation) return false;
+    return operation.selectionSet.selections.some(selection => {
+      return (
+        selection.kind === 'Field' &&
+        selection.name &&
+        selection.name.value.startsWith('__')
+      );
+    });
+  } catch (e) {
+    return false;
+  }
+}

