+/**
+ * Validates that a redirect URL is safe (i.e., a relative path only).
+ * Prevents open redirect attacks by rejecting absolute URLs,
+ * protocol-relative URLs, and other patterns that could redirect
+ * to external domains.
+ */
+export function isValidRedirectUrl(url: string): boolean {
+	if (!url) return false;
+
+	// Reject protocol-relative URLs (e.g., //evil.com)
+	if (url.startsWith('//')) return false;
+
+	// Reject absolute URLs with a scheme (e.g., https://evil.com)
+	if (/^[a-zA-Z][a-zA-Z0-9+\-.]*:/.test(url)) return false;
+
+	// Reject backslash-based redirects (e.g., \/evil.com or \evil.com)
+	if (url.startsWith('\\')) return false;
+
+	// Only allow paths that start with / (relative to the current origin)
+	if (!url.startsWith('/')) return false;
+
+	return true;
+}
