+import { isValidRedirectUrl } from '@/utils/urlUtils';
+
+describe('isValidRedirectUrl', () => {
+	it('should accept valid relative paths', () => {
+		expect(isValidRedirectUrl('/')).toBe(true);
+		expect(isValidRedirectUrl('/workflow/123')).toBe(true);
+		expect(isValidRedirectUrl('/signin?foo=bar')).toBe(true);
+		expect(isValidRedirectUrl('/home#section')).toBe(true);
+	});
+
+	it('should reject empty or falsy values', () => {
+		expect(isValidRedirectUrl('')).toBe(false);
+	});
+
+	it('should reject protocol-relative URLs', () => {
+		expect(isValidRedirectUrl('//evil.com')).toBe(false);
+		expect(isValidRedirectUrl('//evil.com/path')).toBe(false);
+	});
+
+	it('should reject absolute URLs with schemes', () => {
+		expect(isValidRedirectUrl('https://evil.com')).toBe(false);
+		expect(isValidRedirectUrl('http://evil.com')).toBe(false);
+		expect(isValidRedirectUrl('javascript:alert(1)')).toBe(false);
+		expect(isValidRedirectUrl('data:text/html,<h1>hi</h1>')).toBe(false);
+	});
+
+	it('should reject backslash-based redirects', () => {
+		expect(isValidRedirectUrl('\\evil.com')).toBe(false);
+		expect(isValidRedirectUrl('\\/evil.com')).toBe(false);
+	});
+
+	it('should reject paths not starting with /', () => {
+		expect(isValidRedirectUrl('evil.com')).toBe(false);
+		expect(isValidRedirectUrl('foo/bar')).toBe(false);
+	});
+});

