+/**
+ * Sanitize a callback/redirect URL to prevent open redirect attacks.
+ * Strips leading slashes beyond the first one and rejects absolute URLs
+ * pointing to external origins.
+ */
+export function safeRedirectURL(url: string, baseURL?: string): string {
+	// Collapse protocol-relative URLs (//evil.com) to a relative path (/evil.com)
+	let sanitized = url.replace(/^\/\/+/, "/");
+	try {
+		const parsed = new URL(sanitized, baseURL || "http://localhost");
+		if (baseURL && parsed.origin !== new URL(baseURL).origin) {
+			return "/";
+		}
+	} catch {}
+	return sanitized;
+}
