+/**
+ * Validate and sanitize callback URLs to prevent open redirect attacks.
+ * Returns the sanitized URL if valid, or the fallback URL otherwise.
+ */
+export function validateCallbackURL(
+	url: string | undefined,
+	baseURL: string,
+	fallback: string = "/"
+): string {
+	if (!url) return fallback;
+
+	// Block protocol-relative URLs like //evil.com
+	if (url.startsWith("//")) {
+		return fallback;
+	}
+
+	// Allow relative paths
+	if (url.startsWith("/") && !url.startsWith("//")) {
+		return url;
+	}
+
+	// Block absolute URLs to different origins
+	try {
+		const parsed = new URL(url);
+		const base = new URL(baseURL);
+		if (parsed.origin !== base.origin) {
+			return fallback;
+		}
+		return url;
+	} catch {
+		// If URL parsing fails, treat as relative
+		return url.startsWith("/") ? url : fallback;
+	}
+}
