+import type { Permission } from '@directus/types';
+
+export interface FieldCase {
+	when: string;
+	field: string;
+}
+
+/**
+ * Build a map from field name to the list of CASE/WHEN conditions that grant access to that field.
+ * Each permission may grant access to a set of fields (or all fields via '*').
+ * The `when` clause is derived from the permission's `_parsed_filter_knex` or defaults to `1=1` (always true).
+ */
+export function fieldMapFromPermissions(permissions: Permission[]): Map<string, FieldCase[]> {
+	const fieldMap = new Map<string, FieldCase[]>();
+
+	for (const permission of permissions) {
+		const fields = permission.fields ?? [];
+		const hasAllFields = fields.includes('*');
+
+		// Build the WHEN condition from the permission's parsed filter
+		let whenClause: string;
+
+		if ((permission as any)._parsed_filter_knex) {
+			whenClause = (permission as any)._parsed_filter_knex;
+		} else {
+			whenClause = '1=1';
+		}
+
+		const permissionFields = hasAllFields ? ['*'] : fields;
+
+		for (const field of permissionFields) {
+			if (!fieldMap.has(field)) {
+				fieldMap.set(field, []);
+			}
+
+			fieldMap.get(field)!.push({
+				when: whenClause,
+				field,
+			});
+		}
+	}
+
+	return fieldMap;
+}
