+/**
+ * Check if a hostname is allowed based on the allowedHosts configuration.
+ * `localhost` and `*.localhost` are always allowed.
+ * IP addresses (IPv4 and IPv6) are always allowed.
+ */
+export function isAllowedHost(
+  hostname: string,
+  allowedHosts: string[],
+): boolean {
+  // Always allow localhost and *.localhost
+  if (
+    hostname === 'localhost' ||
+    hostname.endsWith('.localhost')
+  ) {
+    return true
+  }
+
+  // Allow IP addresses (not vulnerable to DNS rebinding)
+  if (isIPAddress(hostname)) {
+    return true
+  }
+
+  // Check against user-specified allowed hosts
+  for (const allowed of allowedHosts) {
+    if (hostname === allowed) {
+      return true
+    }
+    // Support wildcard subdomains like `.example.com`
+    if (allowed.startsWith('.') && hostname.endsWith(allowed)) {
+      return true
+    }
+  }
+
+  return false
+}
+
+function isIPAddress(hostname: string): boolean {
+  // IPv4 or IPv6 (including bracketed)
+  return /^(\d{1,3}\.){3}\d{1,3}$/.test(hostname) ||
+    /^[\da-fA-F:]+$/.test(hostname) ||
+    /^\[[\da-fA-F:]+\]$/.test(hostname)
+}
