+++ b/src/trix/models/html_sanitizer.js
@@ -0,0 +1,80 @@
+const allowedAttributes = "style href src width height language class".split(" ")
+const forbiddenProtocols = "javascript:".split(" ")
+const forbiddenElements = "script iframe form noscript".split(" ")
+
+export default class HTMLSanitizer {
+  static sanitize(html, options) {
+    const sanitizer = new this(html, options)
+    sanitizer.sanitize()
+    return sanitizer
+  }
+
+  constructor(html, { allowedAttributes: _allowedAttributes } = {}) {
+    this.allowedAttributes = _allowedAttributes || allowedAttributes
+    this.body = createBodyElementForHTML(html)
+  }
+
+  sanitize() {
+    this.sanitizeElements()
+    return this.sanitizeAttributes()
+  }
+
+  getHTML() {
+    return this.body.innerHTML
+  }
+
+  getBody() {
+    return this.body
+  }
+
+  // Private
+
+  sanitizeElements() {
+    const walker = walkTree(this.body)
+    const nodesToRemove = []
+
+    while (walker.nextNode()) {
+      const node = walker.currentNode
+      switch (node.nodeType) {
+        case Node.ELEMENT_NODE:
+          if (forbiddenElements.includes(node.tagName.toLowerCase())) {
+            nodesToRemove.push(node)
+          }
+          break
+        case Node.COMMENT_NODE:
+          nodesToRemove.push(node)
+          break
+      }
+    }
+
+    nodesToRemove.forEach((node) => node.parentNode.removeChild(node))
+    return this.body
+  }
+
+  sanitizeAttributes() {
+    const walker = walkTree(this.body)
+
+    while (walker.nextNode()) {
+      const node = walker.currentNode
+      if (node.nodeType !== Node.ELEMENT_NODE) continue
+
+      const attributesToRemove = []
+      for (let i = 0; i < node.attributes.length; i++) {
+        const attr = node.attributes[i]
+        if (!this.allowedAttributes.includes(attr.name)) {
+          attributesToRemove.push(attr.name)
+        } else {
+          const value = attr.value
+          if (forbiddenProtocols.some((protocol) => value.trim().toLowerCase().startsWith(protocol))) {
+            attributesToRemove.push(attr.name)
+          }
+        }
+      }
+      attributesToRemove.forEach((attrName) => node.removeAttribute(attrName))
+    }
+
+    return this.body
+  }
+}
+
+function createBodyElementForHTML(html = "") {
+  const doc = document.implementation.createHTMLDocument("")
+  doc.documentElement.innerHTML = html
+  return doc.body
+}
+
+function walkTree(root) {
+  return document.createTreeWalker(root, NodeFilter.SHOW_ALL, null, false)
+}
