+/**
+ * Sanitize HTML content to prevent HTML injection attacks.
+ * Only allows a safe subset of HTML tags and removes potentially dangerous attributes.
+ */
+export function sanitizeHTML(input: string): string {
+	// Allow only a limited set of safe inline formatting tags
+	const allowedTags = new Set(['b', 'i', 'u', 'em', 'strong', 'br', 'blockquote', 'code', 'a', 'ul', 'ol', 'li', 'p', 'span', 'del', 's']);
+
+	// Remove any HTML tags that are not in the allowed list
+	let sanitized = input.replace(/<\/?([a-zA-Z][a-zA-Z0-9]*)\b[^>]*>/gi, (match, tagName) => {
+		const tag = tagName.toLowerCase();
+
+		if (!allowedTags.has(tag)) {
+			return '';
+		}
+
+		// For allowed tags, strip dangerous attributes (only allow href on <a> tags)
+		if (match.startsWith('</')) {
+			return `</${tag}>`;
+		}
+
+		// Strip all attributes except href on anchor tags, and sanitize href
+		const hrefMatch = tag === 'a' ? match.match(/href="(https?:\/\/[^""]*)"/i) : null;
+		return hrefMatch ? `<${tag} href="${hrefMatch[1]}">` : `<${tag}>`;
+	});
+
+	// Remove any event handler attributes that might have slipped through
+	sanitized = sanitized.replace(/\s*on\w+\s*=\s*["'][^"']*["']/gi, '');
+
+	return sanitized;
+}

