@@ -0,0 +1,25 @@
+/**
+ * Sanitize HTML string by removing potentially dangerous elements and attributes.
+ * This is used to prevent XSS when rendering markdown content.
+ */
+export function sanitizeHtml(html) {
+  const doc = new DOMParser().parseFromString(html, 'text/html');
+  
+  // Remove script elements
+  doc.querySelectorAll('script, iframe, object, embed, form').forEach(el => el.remove());
+  
+  // Remove dangerous attributes
+  doc.querySelectorAll('*').forEach(el => {
+    for (const attr of [...el.attributes]) {
+      const name = attr.name.toLowerCase();
+      const value = attr.value.trim().toLowerCase();
+      // Remove event handlers
+      if (name.startsWith('on')) {
+        el.removeAttribute(attr.name);
+      }
+      // Remove javascript: URLs
+      if (['src', 'href', 'action', 'xlink:href'].includes(name) && value.startsWith('javascript:')) {
+        el.removeAttribute(attr.name);
+      }
+    }
+  });
+  
+  return doc.body.innerHTML;
+}

