+};
+
+/**
+ * Check if the provided endpoint is the default endpoint for the given provider.
+ * If no endpoint is provided (undefined/null/empty), it is considered default.
+ * This prevents API key leakage when users set custom base URLs.
+ */
+export const checkIsDefaultEndpoint = (
+  endpoint: string | undefined | null,
+  provider: string,
+): boolean => {
+  // If no custom endpoint is provided, it's the default
+  if (!endpoint) return true;
+
+  const defaultEndpoint = DEFAULT_ENDPOINTS[provider];
+  if (!defaultEndpoint) return false;
+
+  // Normalize URLs for comparison (remove trailing slashes)
+  const normalizedEndpoint = endpoint.replace(/\/+$/, '').toLowerCase();
+  const normalizedDefault = defaultEndpoint.replace(/\/+$/, '').toLowerCase();
+
+  return normalizedEndpoint === normalizedDefault;
+};
