+const ALLOWED_PROTOCOLS = [
+  "http:",
+  "https:",
+  "mailto:",
+  "tel:",
+  "ftp:",
+];
+
+const BLANK_URL = "about:blank";
+
+/**
+ * Sanitizes a URL to prevent XSS attacks by only allowing safe protocols.
+ * Returns "about:blank" for URLs with disallowed protocols.
+ */
+export const sanitizeUrl = (url: string): string => {
+  if (!url) {
+    return url;
+  }
+
+  try {
+    const normalizedUrl = url.trim();
+    // Check for javascript: and other dangerous protocols
+    // Using a decoded version to catch encoded variants like java&#x73;cript:
+    const decoded = decodeURIComponent(normalizedUrl);
+    const urlObj = new URL(decoded, window.location.origin);
+    if (!ALLOWED_PROTOCOLS.includes(urlObj.protocol)) {
+      return BLANK_URL;
+    }
+    return normalizedUrl;
+  } catch {
+    return url;
+  }
+};
