+/**
+ * CSRF protection by validating the Origin header against the Host/URL
+ * for state-changing HTTP methods.
+ */
+
+const CSRF_PROTECTED_METHODS = new Set(['POST', 'PUT', 'DELETE', 'PATCH']);
+
+export function checkCsrf(request: Request): Response | null {
+  const method = request.method.toUpperCase();
+
+  if (!CSRF_PROTECTED_METHODS.has(method)) {
+    return null;
+  }
+
+  const origin = request.headers.get('origin');
+  const contentType = request.headers.get('content-type');
+
+  // If there's no origin header and the content type is JSON,
+  // this is likely a same-origin fetch/XHR request (browsers don't
+  // send application/json from forms)
+  if (!origin && contentType && contentType.includes('application/json')) {
+    return null;
+  }
+
+  if (origin) {
+    const requestUrl = new URL(request.url);
+    const originUrl = new URL(origin);
+
+    if (originUrl.origin === requestUrl.origin) {
+      return null;
+    }
+
+    return new Response('Cross-site request forbidden', {
+      status: 403,
+      statusText: 'Forbidden',
+    });
+  }
+
+  return null;
+}
