+export const sanitize = (html: string): string => {
+    const tempDiv = document.createElement("div");
+    tempDiv.innerHTML = html;
+    
+    // Remove script elements
+    const scripts = tempDiv.querySelectorAll("script");
+    scripts.forEach((script) => {
+        script.remove();
+    });
+    
+    // Remove dangerous elements
+    const dangerousElements = tempDiv.querySelectorAll("iframe, object, embed, applet, form, meta, link, base, svg");
+    dangerousElements.forEach((el) => {
+        el.remove();
+    });
+    
+    // Remove event handler attributes and javascript: URLs from all elements
+    const allElements = tempDiv.querySelectorAll("*");
+    allElements.forEach((el) => {
+        const attrs = Array.from(el.attributes);
+        attrs.forEach((attr) => {
+            const name = attr.name.toLowerCase();
+            // Remove on* event handlers
+            if (name.startsWith("on")) {
+                el.removeAttribute(attr.name);
+            }
+            // Remove javascript: URLs
+            if ((name === "href" || name === "src" || name === "action" || name === "xlink:href") &&
+                attr.value.replace(/\s/g, "").toLowerCase().indexOf("javascript:") === 0) {
+                el.removeAttribute(attr.name);
+            }
+        });
+    });
+    
+    return tempDiv.innerHTML;
+};
