+/**
+ * Sanitize a filesystem path before embedding it into LLM prompts.
+ *
+ * Strips:
+ *  - Unicode control characters (C0, C1, DEL)
+ *  - Unicode format characters (category Cf: zero-width joiners, bidi markers, etc.)
+ *  - Explicit line/paragraph separators (U+2028, U+2029)
+ *  - Carriage returns and newlines
+ *
+ * This prevents prompt injection via specially-crafted directory names.
+ */
+export function sanitizePath(input: string): string {
+	// Remove:
+	//  \x00-\x1f  — C0 control characters (includes \n, \r, \t, etc.)
+	//  \x7f       — DEL
+	//  \x80-\x9f  — C1 control characters
+	//  \u200b-\u200f — zero-width and bidi markers
+	//  \u2028-\u2029 — line/paragraph separators
+	//  \u202a-\u202e — bidi embedding/override controls
+	//  \u2060-\u2069 — word joiner, invisible separators, bidi isolates
+	//  \ufeff     — BOM / zero-width no-break space
+	//  \ufff9-\ufffb — interlinear annotation anchors
+	return input.replace(/[\x00-\x1f\x7f-\x9f\u200b-\u200f\u2028-\u2029\u202a-\u202e\u2060-\u2069\ufeff\ufff9-\ufffb]/g, '');
+}
