+import * as fs from "fs";
+import * as path from "path";
+import fetch from "node-fetch";
+
+/**
+ * Allowed root directory for local file access.
+ * Defaults to the current working directory if not explicitly configured.
+ */
+const LOCAL_MEDIA_ROOT = process.env.OPENCLAW_MEDIA_ROOT
+  ? path.resolve(process.env.OPENCLAW_MEDIA_ROOT)
+  : path.resolve(process.cwd(), "media");
+
+export interface LoadedMedia {
+  buffer: Buffer;
+  filename: string;
+}
+
+/**
+ * Resolve and validate a local file path to ensure it stays within the
+ * allowed LOCAL_MEDIA_ROOT directory. Prevents path traversal attacks.
+ */
+function resolveLocalPath(filePath: string): string {
+  const resolved = path.resolve(LOCAL_MEDIA_ROOT, filePath);
+  const canonical = fs.realpathSync(resolved);
+
+  if (!canonical.startsWith(LOCAL_MEDIA_ROOT + path.sep) && canonical !== LOCAL_MEDIA_ROOT) {
+    throw new Error(
+      `Access denied: path "${filePath}" resolves outside the allowed media root`
+    );
+  }
+
+  return canonical;
+}
+
+/**
+ * Load media from a URL (remote) or a local path (restricted to LOCAL_MEDIA_ROOT).
+ * This is a hardened helper that enforces local-root restrictions to prevent
+ * arbitrary file reads via path traversal.
+ */
+export async function loadMedia(mediaUrl: string): Promise<LoadedMedia> {
+  if (mediaUrl.startsWith("http://") || mediaUrl.startsWith("https://")) {
+    // Fetch remote media
+    const response = await fetch(mediaUrl);
+    if (!response.ok) {
+      throw new Error(
+        `Failed to fetch media from ${mediaUrl}: ${response.statusText}`
+      );
+    }
+    const buffer = Buffer.from(await response.arrayBuffer());
+    const urlPath = new URL(mediaUrl).pathname;
+    const filename = path.basename(urlPath) || "media";
+    return { buffer, filename };
+  }
+
+  // For local paths, enforce that the resolved path is within the allowed root
+  const safePath = resolveLocalPath(mediaUrl);
+
+  if (!fs.existsSync(safePath)) {
+    throw new Error(`Media file not found: ${mediaUrl}`);
+  }
+
+  const buffer = fs.readFileSync(safePath);
+  const filename = path.basename(safePath);
+
+  return { buffer, filename };
+}

