+/**
+ * Show a confirmation dialog to the user and return a promise
+ * that resolves to true if confirmed, false otherwise.
+ */
+export function showConfirmDialog(title: string, message: string): Promise<boolean> {
+  return new Promise((resolve) => {
+    // Use a native confirm dialog for security-critical prompts
+    // to avoid DOM-based spoofing in the app UI
+    const result = window.confirm(`${title}\n\n${message}`);
+    resolve(result);
+  });
+}

