+/**
+ * Security module to prevent sandbox escape via built-in modules
+ * like Puppeteer and Playwright that allow specifying executable paths.
+ */
+
+const DANGEROUS_MODULES = ['puppeteer', 'puppeteer-core', 'playwright', 'playwright-chromium', 'playwright-firefox', 'playwright-webkit']
+
+/**
+ * Creates a proxy wrapper around a browser module (Puppeteer/Playwright)
+ * that strips dangerous launch options like executablePath and unsafe args.
+ */
+function createSafeBrowserProxy(originalModule: any, moduleName: string): any {
+    const handler: ProxyHandler<any> = {
+        get(target, prop, receiver) {
+            const value = Reflect.get(target, prop, receiver)
+
+            // For Puppeteer: wrap .launch()
+            if (moduleName.startsWith('puppeteer') && prop === 'launch') {
+                return function safeLaunch(options?: any) {
+                    const safeOptions = sanitizeLaunchOptions(options)
+                    return value.call(target, safeOptions)
+                }
+            }
+
+            // For Playwright: wrap browser type objects (chromium, firefox, webkit)
+            if (moduleName.startsWith('playwright') && ['chromium', 'firefox', 'webkit'].includes(prop as string)) {
+                return createSafeBrowserTypeProxy(value, moduleName)
+            }
+
+            return value
+        }
+    }
+    return new Proxy(originalModule, handler)
+}
+
+/**
+ * Creates a proxy for Playwright browser type objects that wraps launch/launchPersistentContext
+ */
+function createSafeBrowserTypeProxy(browserType: any, moduleName: string): any {
+    const handler: ProxyHandler<any> = {
+        get(target, prop, receiver) {
+            const value = Reflect.get(target, prop, receiver)
+
+            if (prop === 'launch' || prop === 'launchPersistentContext') {
+                return function safeLaunch(...args: any[]) {
+                    // For launchPersistentContext, options is the second argument
+                    if (prop === 'launchPersistentContext' && args.length >= 2) {
+                        args[1] = sanitizeLaunchOptions(args[1])
+                    } else if (prop === 'launch') {
+                        args[0] = sanitizeLaunchOptions(args[0])
+                    }
+                    return value.apply(target, args)
+                }
+            }
+
+            return value
+        }
+    }
+    return new Proxy(browserType, handler)
+}
+
+// Browser args that could be used for code execution or sandbox escape
+const DANGEROUS_ARGS_PATTERNS = [
+    /--renderer-cmd-prefix/i,
+    /--utility-cmd-prefix/i,
+    /--browser-subprocess-path/i,
+    /--gpu-launcher/i,
+    /--nacl-gdb/i,
+    /--no-sandbox/i
+]
