+const ALLOWED_PROTOCOLS = ["http:", "https:"];
+
+/**
+ * Validates that a URL string uses a safe protocol (http or https).
+ * Throws an error if the URL is invalid or uses a dangerous protocol
+ * (e.g., javascript:, data:, vbscript:).
+ */
+export function validateRedirectUrl(url: string): void {
+  let parsed: URL;
+  try {
+    parsed = new URL(url);
+  } catch {
+    throw new Error(`Invalid redirect URL: ${url}`);
+  }
+
+  if (!ALLOWED_PROTOCOLS.includes(parsed.protocol)) {
+    throw new Error(
+      `Unsafe redirect URL protocol "${parsed.protocol}" in URL: ${url}. Only ${ALLOWED_PROTOCOLS.join(", ")} are allowed.`,
+    );
+  }
+}
+
+export function sanitizeUrl(url: string): string {
+  try {
+    validateRedirectUrl(url);
+    return url;
+  } catch {
+    return "about:blank";
+  }
+}
