+import dns from 'dns';
+import { URL } from 'url';
+
+const PRIVATE_IP_RANGES = [
+  // IPv4 private ranges
+  /^127\./,                          // 127.0.0.0/8 - Loopback
+  /^10\./,                           // 10.0.0.0/8 - Private
+  /^172\.(1[6-9]|2[0-9]|3[0-1])\./,  // 172.16.0.0/12 - Private
+  /^192\.168\./,                     // 192.168.0.0/16 - Private
+  /^0\./,                            // 0.0.0.0/8
+  /^169\.254\./,                     // 169.254.0.0/16 - Link-local
+  /^192\.0\.0\./,                    // 192.0.0.0/24 - IETF Protocol
+  /^192\.0\.2\./,                    // 192.0.2.0/24 - Documentation
+  /^198\.51\.100\./,                 // 198.51.100.0/24 - Documentation
+  /^203\.0\.113\./,                  // 203.0.113.0/24 - Documentation
+  /^198\.1[89]\./,                   // 198.18.0.0/15 - Benchmarking
+  /^100\.(6[4-9]|[7-9][0-9]|1[0-1][0-9]|12[0-7])\./, // 100.64.0.0/10 - Shared
+  /^240\./,                          // 240.0.0.0/4 - Reserved
+  /^255\.255\.255\.255$/,            // Broadcast
+  // IPv6 private ranges
+  /^::1$/,                           // Loopback
+  /^fe80:/i,                         // Link-local
+  /^fc00:/i,                         // Unique local
+  /^fd/i,                            // Unique local
+  /^::$/,                            // Unspecified
+  /^::ffff:127\./i,                  // IPv4-mapped loopback
+  /^::ffff:10\./i,                   // IPv4-mapped private
+  /^::ffff:172\.(1[6-9]|2[0-9]|3[0-1])\./i, // IPv4-mapped private
+  /^::ffff:192\.168\./i,            // IPv4-mapped private
+  /^::ffff:0\./i,                   // IPv4-mapped 0.0.0.0/8
+  /^::ffff:169\.254\./i,            // IPv4-mapped link-local
+];
+
+function isPrivateIP(ip: string): boolean {
+  return PRIVATE_IP_RANGES.some((range) => range.test(ip));
+}
+
+function resolveHostname(hostname: string): Promise<string[]> {
+  return new Promise((resolve, reject) => {
+    dns.resolve(hostname, (err, addresses) => {
+      if (err) {
+        // Try resolve4 and resolve6 as fallback
+        dns.resolve4(hostname, (err4, addresses4) => {
+          if (err4) {
+            dns.resolve6(hostname, (err6, addresses6) => {
+              if (err6) {
+                reject(err6);
+              } else {
+                resolve(addresses6);
+              }
+            });
+          } else {
+            resolve(addresses4);
+          }
+        });
+      } else {
+        resolve(addresses);
+      }
+    });
+  });
+}
+
+export async function isPrivateUrl(urlString: string): Promise<boolean> {
+  try {
+    const url = new URL(urlString);
+    const hostname = url.hostname;
+
+    // Check if hostname is already an IP
+    if (isPrivateIP(hostname)) {
+      return true;
+    }
+
+    // Resolve hostname to IP addresses and check each
+    const addresses = await resolveHostname(hostname);
+    return addresses.some((addr) => isPrivateIP(addr));
+  } catch {
+    // If we can't parse or resolve, block it to be safe
+    return true;
+  }
+}

