+const ALLOWED_PROTOCOLS = new Set([
+  'http:',
+  'https:',
+  'mailto:',
+  'tel:',
+]);
+
+const SAFE_URL_FALLBACK = 'about:blank';
+
+/**
+ * Sanitize a URL to prevent XSS via dangerous protocols such as `javascript:`,
+ * `data:` or `vbscript:`. Only URLs whose protocol is in the allowlist are
+ * returned; all others are replaced with `about:blank`.
+ */
+export function sanitizeUrl(url: string): string {
+  try {
+    const parsed = new URL(url);
+    return ALLOWED_PROTOCOLS.has(parsed.protocol) ? url : SAFE_URL_FALLBACK;
+  } catch {
+    // Relative URLs or malformed strings – keep as-is only if they don't look
+    // like a dangerous protocol.
+    const trimmed = url.replace(/[\s\0]+/g, '').toLowerCase();
+    if (/^(javascript|data|vbscript)\s*:/i.test(trimmed)) {
+      return SAFE_URL_FALLBACK;
+    }
+    return url;
+  }
+}

