+/**
+ * Escapes a JSON string for safe embedding within a <script> tag in HTML.
+ * This prevents XSS attacks by escaping characters that could break out of
+ * the script context or be interpreted as HTML.
+ */
+export function htmlEscapeJsonString(jsonString: string): string {
+  return jsonString.replace(
+    /[<>&\u2028\u2029]/g,
+    (char) => {
+      switch (char) {
+        case "<": return "\\u003c";
+        case ">": return "\\u003e";
+        case "&": return "\\u0026";
+        case "\u2028": return "\\u2028";
+        case "\u2029": return "\\u2029";
+        default: return char;
+      }
+    }
+  );
+}
