--- /dev/null
+++ b/server/auth.js
@@ -0,0 +1,47 @@
+const { R } = require("redbean-node");
+const jwt = require("jsonwebtoken");
+const { log } = require("../src/util");
+
+/**
+ * Generate a new JWT token for a user and store the jti in the database
+ * @param {object} user User object
+ * @param {string} jwtSecret JWT secret
+ * @returns {string} JWT token
+ */
+async function generateToken(user, jwtSecret) {
+    const jti = require("crypto").randomUUID();
+    const token = jwt.sign({
+        username: user.username,
+        user_id: user.id,
+        jti: jti,
+    }, jwtSecret);
+
+    // Store the jti in the database
+    let session = R.dispense("user_session");
+    session.user_id = user.id;
+    session.jti = jti;
+    session.created_date = new Date().toISOString();
+    await R.store(session);
+
+    return token;
+}
+
+/**
+ * Revoke all sessions for a user
+ * @param {number} userID User ID
+ * @returns {void}
+ */
+async function revokeAllTokens(userID) {
+    await R.exec("DELETE FROM user_session WHERE user_id = ?", [userID]);
+    log.info("auth", `All sessions revoked for user ID: ${userID}`);
+}
+
+/**
+ * Check if a token's jti is still valid
+ * @param {string} jti JWT ID
+ * @returns {boolean} Whether the session is valid
+ */
+async function isSessionValid(jti) {
+    const session = await R.findOne("user_session", " jti = ? ", [jti]);
+    return session !== null;
+}
+
+module.exports = {
+    generateToken,
+    revokeAllTokens,
+    isSessionValid,
+};
