+import { Field, fieldAffectsData, fieldHasSubFields } from './config/types';
+import { PayloadRequest } from '../express/types';
+
+type Args = {
+  fields: Field[];
+  req: PayloadRequest;
+  overrideAccess?: boolean;
+}
+
+/**
+ * Returns a Set of field paths that are allowed to be queried.
+ * Fields that are hidden or that the user does not have read access to are excluded.
+ */
+const getFieldsToQuery = async ({
+  fields,
+  req,
+  overrideAccess = false,
+}: Args): Promise<Set<string>> => {
+  const allowed = new Set<string>();
+
+  const traverseFields = async (fieldsToTraverse: Field[], parentPath = '') => {
+    const promises = fieldsToTraverse.map(async (field) => {
+      if (fieldAffectsData(field)) {
+        const fieldPath = parentPath ? `${parentPath}.${field.name}` : field.name;
+
+        // Skip hidden fields
+        if (field.hidden) {
+          return;
+        }
+
+        // Check field-level access
+        if (!overrideAccess && field.access?.read) {
+          const hasAccess = await field.access.read({ req, id: null, data: null, siblingData: null, doc: null });
+          if (!hasAccess) {
+            return;
+          }
+        }
+
+        allowed.add(fieldPath);
+
+        // Traverse sub-fields if applicable
+        if (fieldHasSubFields(field)) {
+          await traverseFields(field.fields, fieldPath);
+        }
+
+        if (field.type === 'tabs') {
+          for (const tab of field.tabs) {
+            await traverseFields(tab.fields, fieldPath);
+          }
+        }
+      } else {
+        // Non-data fields like rows, collapsibles, tabs (unnamed)
+        if (fieldHasSubFields(field)) {
+          await traverseFields(field.fields, parentPath);
+        }
+        if (field.type === 'tabs') {
+          for (const tab of field.tabs) {
+            if ('name' in tab && tab.name) {
+              const tabPath = parentPath ? `${parentPath}.${tab.name}` : tab.name;
+              allowed.add(tabPath);
+              await traverseFields(tab.fields, tabPath);
+            } else {
+              await traverseFields(tab.fields, parentPath);
+            }
+          }
+        }
+      }
+    });
+
+    await Promise.all(promises);
+  };
+
+  await traverseFields(fields);
+
+  return allowed;
+};
+
+export default getFieldsToQuery;
