+/**
+ * Check if a field path is restricted (hidden or no read access)
+ */
+async function isFieldRestricted({ fields, path, req, overrideAccess }: {
+  fields: Field[];
+  path: string;
+  req?: PayloadRequest;
+  overrideAccess?: boolean;
+}): Promise<boolean> {
+  if (overrideAccess) return false;
+  if (!fields || !path) return false;
+
+  const segments = path.split('.');
+  return checkFieldPath(fields, segments, req);
+}
+
+async function checkFieldPath(fields: Field[], segments: string[], req?: PayloadRequest): Promise<boolean> {
+  if (segments.length === 0) return false;
+
+  const [current, ...rest] = segments;
+
+  for (const field of fields) {
+    if (fieldAffectsData(field)) {
+      if (field.name === current) {
+        // Check if field is hidden
+        if (field.hidden) {
+          return true;
+        }
+
+        // Check field-level read access
+        if (req && field.access?.read) {
+          try {
+            const hasAccess = await field.access.read({ req, id: null, data: null, siblingData: null, doc: null });
+            if (!hasAccess) {
+              return true;
+            }
+          } catch (e) {
+            return true;
+          }
+        }
+
+        // If there are more segments, traverse into sub-fields
+        if (rest.length > 0) {
+          if (fieldHasSubFields(field)) {
+            return checkFieldPath(field.fields, rest, req);
+          }
+          if (field.type === 'tabs') {
+            for (const tab of field.tabs) {
+              const result = await checkFieldPath(tab.fields, rest, req);
+              if (result) return true;
+            }
+          }
+        }
+
+        return false;
+      }
+    } else if (fieldHasSubFields(field)) {
+      const result = await checkFieldPath(field.fields, segments, req);
+      if (result) return true;
+    } else if (field.type === 'tabs') {
+      for (const tab of field.tabs) {
+        const result = await checkFieldPath(tab.fields, segments, req);
+        if (result) return true;
+      }
+    }
+  }
+
+  return false;
+}
