+// Seed OpenSSL's CSPRNG with random bytes from the host at runtime
+// rather than using a fixed seed baked into the WebAssembly module.
+bool seed_random_from_host() {
+  uint8_t seed[32];
+  auto res = host_api::Random::get_bytes(sizeof(seed), seed);
+  if (!res) {
