+ * Convert a string to IRC lowercase according to the specified casemapping.
+ * This is critical for security: IRC considers certain characters equivalent,
+ * and failing to normalize can allow channel confusion attacks (CVE-2022-39203).
+ */
+export function toIrcLowerCase(str: string, caseMapping = "rfc1459"): string {
+    let result = str.toLowerCase();
+    if (caseMapping === "rfc1459") {
+        // RFC 1459: {}|~ are the uppercase equivalents of []\^
+        result = result
