+/**
+ * Sanitizes SVG input to prevent directory traversal and local file inclusion attacks.
+ *
+ * Removes attributes that reference local file paths containing directory traversal sequences
+ * and strips potentially dangerous tags that could be used to include external resources.
+ *
+ * @param {string} input - the SVG input to sanitize
+ * @return {string} the sanitized SVG input
+ */
+function sanitize(input) {
+  if (!input || typeof input !== 'string') {
+    return input;
+  }
+
+  // Remove attributes containing directory traversal patterns in href, src, xlink:href, and url() values
+  // Match href="...", xlink:href="...", src="..." attributes that contain traversal sequences
+  const traversalPattern = /\.\.[/\\]/;
+
+  // Sanitize href, xlink:href, and src attributes that contain path traversal
+  input = input.replace(
+    /(href|src|xlink:href)\s*=\s*["']([^"']*)["']/gi,
+    (match, attr, value) => {
+      const decodedValue = decodeURIComponent(value);
+      if (traversalPattern.test(decodedValue) || traversalPattern.test(value)) {
+        return `${attr}=""`;
+      }
+      // Block file:// protocol references
+      if (/^\s*file:/i.test(decodedValue)) {
+        return `${attr}=""`;
+      }
+      return match;
+    }
+  );
+
+  return input;
+}
+
+module.exports = { sanitize };

