+import { ExpressionError } from './errors/expression.error';
+
+/**
+ * List of patterns that are banned from expressions to prevent sandbox escapes.
+ * These patterns block access to constructors, prototypes, and other mechanisms
+ * that could be used to execute arbitrary code.
+ */
+const BANNED_PATTERNS: RegExp[] = [
+	// Block direct constructor access
+	/\bconstructor\b/i,
+	// Block __proto__ access
+	/__proto__/i,
+	// Block prototype access
+	/\bprototype\b/i,
+	// Block process access (node.js process object)
+	/\bprocess\b/i,
+	// Block require calls
+	/\brequire\b/i,
+	// Block global object access
+	/\bglobal\b/i,
+	/\bglobalThis\b/i,
+	// Block eval and Function constructor
+	/\beval\b/i,
+	/\bFunction\b/i,
+	// Block import expressions
+	/\bimport\b/i,
+	// Block child_process and similar
+	/child_process/i,
+	/\bexecSync\b/i,
+	/\bexecFileSync\b/i,
+	/\bspawnSync\b/i,
+	/\bexec\b(?!\s*\(.*\/.*\/)/i,
+	// Block Reflect and Proxy
+	/\bReflect\b/i,
+	/\bProxy\b/i,
+	// Block Buffer access (can be used for exploits)
+	/\bBuffer\b/i,
+	// Block __defineGetter__ and __defineSetter__
+	/__defineGetter__/i,
+	/__defineSetter__/i,
+	/__lookupGetter__/i,
+	/__lookupSetter__/i,
+	// Block Symbol.species and other symbol-based escapes
+	/Symbol\s*\.\s*species/i,
+	// Block getOwnPropertyDescriptor and defineProperty (used for sandbox escapes)
+	/\bgetOwnPropertyDescriptor\b/i,
+	/\bdefineProperty\b/i,
+	/\bdefineProperties\b/i,
+	// Block arguments.callee
+	/\barguments\s*\.\s*callee\b/i,
+	// Block WebAssembly
+	/\bWebAssembly\b/i,
+	// Block SharedArrayBuffer
+	/\bSharedArrayBuffer\b/i,
+	// Block Atomics
+	/\bAtomics\b/i,
+];
+
+/**
+ * Validates that an expression does not contain any banned patterns that could
+ * be used to escape the expression sandbox and execute arbitrary code.
+ *
+ * @param expression - The expression string to validate
+ * @returns The original expression if it passes validation
+ * @throws ExpressionError if a banned pattern is detected
+ */
+export function ensureNotBanned(expression: string): string {
+	// Remove string literals to avoid false positives, but keep their placeholders
+	const withoutStrings = expression
+		.replace(/'(?:[^'\\]|\\.)*'/g, '""')
+		.replace(/"(?:[^"\\]|\\.)*"/g, '""')
+		.replace(/`(?:[^`\\]|\\.)*`/g, '""');
+
+	for (const pattern of BANNED_PATTERNS) {
+		if (pattern.test(withoutStrings)) {
+			throw new ExpressionError(
+				`Expression contains a blocked pattern: ${pattern.source}`,
+			);
+		}
+	}
+	return expression;
+}
