+import { ensureNotBanned } from '../src/ExpressionSandboxing';
+
+describe('ExpressionSandboxing', () => {
+	describe('ensureNotBanned', () => {
+		it('should allow normal expressions', () => {
+			expect(ensureNotBanned('{{ $json.name }}')).toBe('{{ $json.name }}');
+			expect(ensureNotBanned('{{ $json.value + 1 }}')).toBe('{{ $json.value + 1 }}');
+			expect(ensureNotBanned('{{ "hello world" }}')).toBe('{{ "hello world" }}');
+		});
+
+		it('should block constructor access', () => {
+			expect(() => ensureNotBanned('{{ "".constructor }}')).toThrow();
+			expect(() => ensureNotBanned('{{ [].constructor }}')).toThrow();
+		});
+
+		it('should block __proto__ access', () => {
+			expect(() => ensureNotBanned('{{ {}.__proto__ }}')).toThrow();
+		});
+
+		it('should block prototype access', () => {
+			expect(() => ensureNotBanned('{{ Object.prototype }}')).toThrow();
+		});
+
+		it('should block process access', () => {
+			expect(() => ensureNotBanned('{{ process.env }}')).toThrow();
+		});
+
+		it('should block require', () => {
+			expect(() => ensureNotBanned('{{ require("child_process") }}')).toThrow();
+		});
+
+		it('should block eval', () => {
+			expect(() => ensureNotBanned('{{ eval("code") }}')).toThrow();
+		});
+
+		it('should block Function constructor', () => {
+			expect(() => ensureNotBanned('{{ Function("return 1")() }}')).toThrow();
+		});
+
+		it('should block global access', () => {
+			expect(() => ensureNotBanned('{{ global }}')).toThrow();
+			expect(() => ensureNotBanned('{{ globalThis }}')).toThrow();
+		});
+
+		it('should block Reflect', () => {
+			expect(() => ensureNotBanned('{{ Reflect.get({}, "a") }}')).toThrow();
+		});
+
+		it('should not false-positive on string contents', () => {
+			// The word "constructor" inside a string literal should not trigger
+			expect(ensureNotBanned('{{ "the constructor of the building" }}')).toBe(
+				'{{ "the constructor of the building" }}',
+			);
+		});
+
+		it('should block defineProperty', () => {
+			expect(() =>
+				ensureNotBanned('{{ Object.defineProperty({}, "a", {}) }}'),
+			).toThrow();
+		});
+
+		it('should block import', () => {
+			expect(() => ensureNotBanned('{{ import("fs") }}')).toThrow();
+		});
+
+		it('should block WebAssembly', () => {
+			expect(() => ensureNotBanned('{{ WebAssembly }}')).toThrow();
+		});
+	});
+});

