+/**
+ * Expression sandboxing utilities to prevent RCE through expression evaluation.
+ *
+ * This module provides proxy-based protection to prevent prototype chain traversal
+ * and access to dangerous runtime objects from within expression evaluation contexts.
+ */
+
+const BLOCKED_KEYS = new Set([
+	'constructor',
+	'__proto__',
+	'__defineGetter__',
+	'__defineSetter__',
+	'__lookupGetter__',
+	'__lookupSetter__',
+	'prototype',
+]);
+
+const BLOCKED_CONSTRUCTORS = new Set([
+	Function,
+	Object.getPrototypeOf(async function () {}).constructor, // AsyncFunction
+	Object.getPrototypeOf(function* () {}).constructor, // GeneratorFunction
+]);
+
+/**
+ * Creates a sandboxed proxy around a data object that prevents
+ * access to dangerous properties that could be used for RCE.
+ */
+export function createSandboxProxy<T extends object>(obj: T): T {
+	return new Proxy(obj, {
+		get(target, prop, receiver) {
+			if (typeof prop === 'string' && BLOCKED_KEYS.has(prop)) {
+				return undefined;
+			}
+
+			const value = Reflect.get(target, prop, receiver);
+
+			// Block access to Function constructors
+			if (typeof value === 'function' && BLOCKED_CONSTRUCTORS.has(value)) {
+				return undefined;
+			}
+
+			// Recursively proxy objects to prevent deep prototype traversal
+			if (value !== null && typeof value === 'object' && !Array.isArray(value)) {
+				return createSandboxProxy(value as object);
+			}
+
+			return value;
+		},
+
+		has(target, prop) {
+			if (typeof prop === 'string' && BLOCKED_KEYS.has(prop)) {
+				return false;
+			}
+			return Reflect.has(target, prop);
+		},
+	});
+}
+
+/**
+ * Strips dangerous properties from the global scope available to expressions.
+ */
+export function createSafeGlobals(): Record<string, unknown> {
+	return {
+		// Safe built-ins
+		Math,
+		Date,
+		JSON,
+		Number,
+		String,
+		Boolean,
+		Array,
+		Object: Object.freeze({
+			keys: Object.keys,
+			values: Object.values,
+			entries: Object.entries,
+			assign: Object.assign,
+			fromEntries: Object.fromEntries,
+		}),
+		parseInt,
+		parseFloat,
+		isNaN,
+		isFinite,
+		encodeURIComponent,
+		decodeURIComponent,
+		encodeURI,
+		decodeURI,
+		undefined,
+		NaN,
+		Infinity,
+		// Explicitly block dangerous globals
+		process: undefined,
+		require: undefined,
+		global: undefined,
+		globalThis: undefined,
+		eval: undefined,
+		Function: undefined,
+		module: undefined,
+		exports: undefined,
+	};
+}
