+import path from 'path';
+
+export function validateFilePath(filePath: string, allowedBaseDirs?: string[]): boolean {
+	const resolved = path.resolve(filePath);
+	// Prevent path traversal - if allowedBaseDirs specified, ensure path is within them
+	if (allowedBaseDirs && allowedBaseDirs.length > 0) {
+		return allowedBaseDirs.some((dir) => resolved.startsWith(path.resolve(dir)));
+	}
+	// At minimum, reject obvious traversal attempts
+	const normalized = path.normalize(filePath);
+	return !normalized.includes('..' + path.sep) && !normalized.startsWith('..');
+}
