+/**
+ * Provides a hardened proxy wrapper for expression evaluation contexts
+ * to prevent prototype pollution and sandbox escape attacks.
+ */
+
+const BLOCKED_KEYS = new Set([
+	'constructor',
+	'__proto__',
+	'__defineGetter__',
+	'__defineSetter__',
+	'__lookupGetter__',
+	'__lookupSetter__',
+	'prototype',
+]);
