+const BLOCKED_CONSTRUCTORS = new Set([
+	Function,
+]);
+
+export function createSandboxedContext<T extends object>(context: T): T {
+	return new Proxy(context, {
+		get(target, prop, receiver) {
+			if (typeof prop === 'string' && BLOCKED_KEYS.has(prop)) {
+				return undefined;
+			}
+
+			const value = Reflect.get(target, prop, receiver);
+
+			if (typeof value === 'function' && BLOCKED_CONSTRUCTORS.has(value)) {
+				return undefined;
+			}
+
+			// Recursively wrap objects to prevent deep property escape
+			if (value !== null && typeof value === 'object' && !ArrayBuffer.isView(value)) {
+				return createSandboxedContext(value);
+			}
+
+			return value;
+		},
+
+		has(target, prop) {
+			if (typeof prop === 'string' && BLOCKED_KEYS.has(prop)) {
+				return false;
+			}
+			return Reflect.has(target, prop);
+		},
+
+		set(target, prop, value) {
+			if (typeof prop === 'string' && BLOCKED_KEYS.has(prop)) {
+				return false;
+			}
+			return Reflect.set(target, prop, value);
+		},
+
+		getPrototypeOf() {
+			return null;
+		},
+	});
+}
