+	
+	// Freeze String.prototype
+	var strProto = String.prototype;
+	Object.freeze(strProto);
+	
+	// Freeze Number.prototype
+	var numProto = Number.prototype;
+	Object.freeze(numProto);
+	
+	// Freeze Boolean.prototype
+	var boolProto = Boolean.prototype;
+	Object.freeze(boolProto);
+	
+	// Freeze RegExp.prototype
+	var regexpProto = RegExp.prototype;
+	Object.freeze(regexpProto);
+})();
