+++ b/src/middleware/dnsRebindingProtection.js
@@ -0,0 +1,72 @@
+/**
+ * Middleware to protect against DNS rebinding attacks.
+ * Validates that the Host header in incoming requests matches expected/allowed values.
+ * @module middleware/dnsRebindingProtection
+ */
+
+/**
+ * List of hostnames that are always considered safe (loopback addresses).
+ */
+const DEFAULT_ALLOWED_HOSTS = [
+    'localhost',
+    '127.0.0.1',
+    '::1',
+    '[::1]',
+    '0.0.0.0',
+];
+
+/**
+ * Check if a hostname is a loopback address.
+ * @param {string} hostname - The hostname to check
+ * @returns {boolean} True if the hostname is a loopback address
+ */
+function isLoopbackHost(hostname) {
+    return hostname === 'localhost' ||
+           hostname.startsWith('127.') ||
+           hostname === '::1' ||
+           hostname === '[::1]' ||
+           hostname === '0.0.0.0';
+}
+
+/**
+ * Creates DNS rebinding protection middleware.
+ * @param {object} options - Configuration options
+ * @param {boolean} [options.disabled=false] - Whether protection is disabled
+ * @param {boolean} [options.listen=false] - Whether server listens on all interfaces
+ * @param {string[]} [options.allowedHosts=[]] - Additional allowed hostnames
+ * @param {function} [options.log] - Logging function
+ * @returns {function} Express middleware
+ */
+function createDnsRebindingProtection(options = {}) {
+    const {
+        disabled = false,
+        listen = false,
+        allowedHosts = [],
+        log = console.warn,
+    } = options;
+
+    return function dnsRebindingProtection(req, res, next) {
+        // If protection is explicitly disabled, skip
+        if (disabled) {
+            return next();
+        }
+
+        // When listening on all interfaces, skip (user has explicitly opted in)
+        if (listen) {
+            return next();
+        }
+
+        const host = req.headers.host;
+        if (!host) {
+            return next();
+        }
+
+        const hostname = host.split(':')[0].toLowerCase();
+
+        const allAllowed = [...DEFAULT_ALLOWED_HOSTS, ...allowedHosts.map(h => h.toLowerCase())];
+
+        if (isLoopbackHost(hostname) || allAllowed.includes(hostname)) {
+            return next();
+        }
+
+        log(`Blocked request with unexpected Host header: ${host}`);
+        log('This may be a DNS rebinding attack. If this is legitimate, add the host to allowedHosts.');
+        res.status(403).send('Forbidden: Invalid Host header. Possible DNS rebinding attack detected.');
+    };
+}
+
+module.exports = {
+    createDnsRebindingProtection,
+    isLoopbackHost,
+    DEFAULT_ALLOWED_HOSTS,
+};

