+export interface ParsedFilter {
+    column: string
+    operator: string
+    value: string | number | boolean
+}
+
+const ALLOWED_OPERATORS = new Set([
+    'eq', 'neq', 'gt', 'gte', 'lt', 'lte',
+    'like', 'ilike', 'is', 'in',
+    'cs', 'cd', 'sl', 'sr', 'nxl', 'nxr',
+    'adj', 'ov', 'fts', 'plfts', 'phfts', 'wfts'
+])
+
+/**
+ * Safely parses Supabase RPC filter expressions without using eval or new Function.
+ * Only allows chained .filter("column", "operator", value) calls.
+ */
+export class FilterParser {
+    parse(input: string): ParsedFilter[] {
+        if (!input || typeof input !== 'string') {
+            return []
+        }
+
+        const filters: ParsedFilter[] = []
+        // Match filter(...) calls, allowing optional leading dot and chaining
+        // Pattern: filter(<arg1>, <arg2>, <arg3>)
+        const filterRegex = /\.?\s*filter\s*\(\s*("(?:[^"\\]|\\.)*"|'(?:[^'\\]|\\.)*')\s*,\s*("(?:[^"\\]|\\.)*"|'(?:[^'\\]|\\.)*')\s*,\s*("(?:[^"\\]|\\.)*"|'(?:[^'\\]|\\.)*'|[-+]?\d+(?:\.\d+)?|true|false)\s*\)/g
+
+        // Validate that the entire input only consists of filter calls, dots, semicolons, and whitespace
+        const sanitized = input.replace(filterRegex, '').replace(/[.\s;]/g, '')
+        if (sanitized.length > 0) {
+            throw new Error(
+                'Invalid Supabase RPC filter expression. Only chained .filter() calls are allowed. ' +
+                'Example: filter("metadata->a::int", "gt", 5).filter("metadata->>stuff", "eq", "right")'
+            )
+        }
+
+        let match: RegExpExecArray | null
+        while ((match = filterRegex.exec(input)) !== null) {
