+import type { SimpleGitPlugin } from './simple-git-plugin';
+import { GitPluginError } from '../errors/git-plugin-error';
+
+function isUnsafeArgument(arg: string): boolean {
+   // Block ext:: protocol which can execute arbitrary commands
+   if (/^ext::/.test(arg)) {
+      return true;
+   }
+   return false;
+}
+
+function isUnsafeRemote(remote: string): boolean {
+   if (/^ext::/.test(remote)) {
+      return true;
+   }
+   // Block arguments starting with - in remote position to prevent option injection
+   if (/^-/.test(remote)) {
+      return true;
+   }
+   return false;
+}
+
+export function blockUnsafeOperationsPlugin(): SimpleGitPlugin<'spawn.args'> {
+   return {
+      type: 'spawn.args',
+      action(args, _context) {
+         // Identify commands that take remote URLs
+         const command = args[0];
+         if (['clone', 'pull', 'push', 'fetch', 'ls-remote'].includes(command)) {
+            // Check all arguments after the command for unsafe patterns
+            for (let i = 1; i < args.length; i++) {
+               const arg = args[i];
+               if (isUnsafeArgument(arg)) {
+                  throw new GitPluginError(
+                     undefined,
+                     'blockUnsafeOperationsPlugin',
+                     `Blocking unsafe argument: ${arg}`
+                  );
+               }
+            }
+         }
+         return args;
+      },
+   };
+}
