+/**
+ * Sanitize SVG content to remove potentially dangerous elements and attributes
+ * that could lead to XSS or arbitrary code execution.
+ */
+const sanitizeSVG = (data: Buffer): Buffer => {
+  let svgContent = data.toString('utf-8');
+
+  // Remove script tags and their content
+  svgContent = svgContent.replace(/<script[\s\S]*?<\/script>/gi, '');
+  svgContent = svgContent.replace(/<script[\s\S]*?\/>/gi, '');
+
+  // Remove event handler attributes (on*)
+  svgContent = svgContent.replace(/\s+on\w+\s*=\s*(?:"[^"]*"|'[^']*'|[^\s>]+)/gi, '');
+
+  // Remove javascript: URIs
+  svgContent = svgContent.replace(/href\s*=\s*["']?\s*javascript\s*:/gi, 'href="');
+  svgContent = svgContent.replace(/xlink:href\s*=\s*["']?\s*javascript\s*:/gi, 'xlink:href="');
+
+  // Remove data: URIs that could contain scripts
+  svgContent = svgContent.replace(/href\s*=\s*["']?\s*data\s*:\s*text\/html/gi, 'href="');
+  svgContent = svgContent.replace(/xlink:href\s*=\s*["']?\s*data\s*:\s*text\/html/gi, 'xlink:href="');
+
+  // Remove foreignObject elements which can embed HTML
+  svgContent = svgContent.replace(/<foreignObject[\s\S]*?<\/foreignObject>/gi, '');
+  svgContent = svgContent.replace(/<foreignObject[\s\S]*?\/>/gi, '');
+
+  return Buffer.from(svgContent, 'utf-8');
+};
+
+export default sanitizeSVG;
