+package org.apache.streampipes.rest.impl;
+
+import org.apache.streampipes.model.client.endpoint.ExtensionsServiceEndpoint;
+import org.apache.streampipes.storage.management.StorageDispatcher;
+
+import org.slf4j.Logger;
+import org.slf4j.LoggerFactory;
+
+import java.net.URI;
+import java.net.URISyntaxException;
+import java.util.List;
+
+public class PipelineElementImportUtils {
+
+  private static final Logger LOG = LoggerFactory.getLogger(PipelineElementImportUtils.class);
+
+  /**
+   * Validates that the provided endpoint URI belongs to a registered extensions service endpoint.
+   * This prevents SSRF attacks by ensuring that only known/registered service endpoints
+   * can be used to install pipeline elements.
+   *
+   * @param endpointUri the URI to validate
+   * @return true if the URI belongs to a registered endpoint, false otherwise
+   */
+  public static boolean isValidEndpoint(String endpointUri) {
+    try {
+      URI uri = new URI(endpointUri);
+      String host = uri.getHost();
+      int port = uri.getPort();
+      String scheme = uri.getScheme();
+
+      if (host == null || scheme == null) {
+        LOG.warn("Invalid endpoint URI provided: {}", endpointUri);
+        return false;
+      }
+
+      // Only allow http and https schemes
+      if (!"http".equalsIgnoreCase(scheme) && !"https".equalsIgnoreCase(scheme)) {
+        LOG.warn("Disallowed URI scheme in endpoint: {}", endpointUri);
+        return false;
+      }
+
+      List<ExtensionsServiceEndpoint> registeredEndpoints =
+          StorageDispatcher.INSTANCE.getNoSqlStore().getExtensionsServiceEndpointStorage().getAll();
+
+      return registeredEndpoints.stream()
+          .anyMatch(endpoint -> {
+            URI registeredUri = URI.create(endpoint.getEndpointUrl());
+            return host.equalsIgnoreCase(registeredUri.getHost())
+                && port == registeredUri.getPort();
+          });
+    } catch (URISyntaxException e) {
+      LOG.warn("Could not parse endpoint URI: {}", endpointUri, e);
+      return false;
+    }
+  }
+}
